 const root=document.getElementById('culture-case-studies'),page=root.querySelector('[data-detail=dungeon]'),lab=page.querySelector('#dg-live'),frame=page.querySelector('[data-dungeon-frame]'),status=page.querySelector('[data-dg-status]'),loading=page.querySelector('[data-dg-loading]'),guide=page.querySelector('[data-dg-guide-note]'),reduced=matchMedia('(prefers-reduced-motion:reduce)'),presentation="/* Host presentation only; the source app, model, planner and UI handlers are unchanged. */\nbody{background:#101117;background-image:none;}\nbody>header{display:none;}\nbody>main{max-width:none;padding:24px 5% 32px;gap:0;}\nbody>main>div:first-child{display:none;}\nbody>main>div.grid{grid-template-columns:minmax(0,1fr);gap:28px;}\nbody>main>div.grid>div:first-child>div:first-child{gap:22px;}\nbody>main aside{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px;align-items:start;}\nbody>main aside>section{height:100%;min-width:0;}\nbody>main section[aria-label=\"Controls\"]{padding:20px;gap:20px;margin-top:12px;}\nbody>main section[aria-label=\"Controls\"] [data-tour=\"horizon\"]{max-width:800px;}\n.text-label,.text-label-dim{color:#acacb1;}\n.text-mono-xs{font-size:13px;line-height:1.65;}\n.world-grid .world-tile{font-size:clamp(12px,1.7vw,23px);}\ninput[type=\"range\"]{min-height:36px;}\nbody>main button{min-height:44px;}\nsection[aria-label=\"Controls\"] label>span{min-height:44px;display:inline-flex;align-items:center;}\n[data-tour=\"move-pad\"] button{height:44px;width:44px;}\n[data-dg-focus]{outline:2px solid #ff419f;outline-offset:6px;}\nbody.dg-touring main{padding-top:16px;}\n.dg-exit-fullscreen{display:none;}\nbody.dg-fullscreen>main{max-width:1600px;margin-inline:auto;padding-top:75px;}\nbody.dg-fullscreen>.dg-exit-fullscreen{display:block;position:fixed;z-index:100;right:20px;top:14px;min-height:44px;padding:10px 15px;background:#101117;border:1px solid #26c5ff;color:#26c5ff;font:12px/1.5 monospace;cursor:pointer;}\n@media(max-width:800px){\n body>main{padding:20px 6% 30px;}\n body>main>div.grid>div:first-child>div:first-child{grid-template-columns:1fr;gap:20px;}\n body>main aside{grid-template-columns:1fr;gap:18px;}\n .world-grid .world-tile{font-size:clamp(10px,3.2vw,15px);}\n .text-mono-xs{font-size:12px;}\n body>main section[aria-label=\"Controls\"]{padding:15px;}\n}\n";
 let resizeObserver,mutationObserver,pending=false,started=false,touring=false,queuedTarget=null,frameDocument=null,lastStatus='',needsLanding=false;
